import java.io.File;
import java.io.IOException;

public class FileMetadataExample {
    public static void main(String[] args) throws IOException {
        var configFile = new File("application.properties");

        // Check existence and type
        if (configFile.exists()) {
            System.out.println("Is file: " + configFile.isFile());
            System.out.println("Is directory: " + configFile.isDirectory());
            System.out.println("Size: " + configFile.length() + " bytes");
            System.out.println("Last modified: " + configFile.lastModified());
        } else {
            configFile.createNewFile(); // Creates empty file
        }

        var logDir = new File("logs");
        if (!logDir.exists()) {
            logDir.mkdir(); // Creates single directory
        }

        var nestedDir = new File("data/cache/temp");
        nestedDir.mkdirs(); // Creates entire path including parents

        System.out.println("Absolute path: " + configFile.getAbsolutePath());
    }
}

import java.nio.file.*;
import java.io.IOException;
import java.util.Comparator;

public class FileSystemOperations {
    public static void main(String[] args) throws IOException {
        var configFile = Path.of("config", "application.properties");

        // Create parent directories first, then file
        Files.createDirectories(configFile.getParent());
        if (!Files.exists(configFile)) {
            Files.createFile(configFile); // Throws if already exists
        }

        // Create nested directory structure in one call
        var logDir = Path.of("logs", "archive", "2024");
        Files.createDirectories(logDir); // Creates all parents if missing

        // Check existence and type
        if (Files.exists(configFile) && Files.isRegularFile(configFile)) {
            System.out.println("Config file ready");
        }

        // Delete file (throws if missing)
        Files.delete(configFile);

        // Delete directory recursively - walk tree in reverse order
        var tempDir = Path.of("temp");
        if (Files.exists(tempDir)) {
            Files.walk(tempDir)
                 .sorted(Comparator.reverseOrder()) // Delete children before parents
                 .forEach(path -> {
                     try { Files.delete(path); }
                     catch (IOException e) { throw new RuntimeException(e); }
                 });
        }
    }
}

