import java.nio.file.Path;

public class CrossPlatformPaths {
    public static void main(String[] args) {
        // Build paths without hardcoding separators
        var configDir = Path.of("config", "environments", "prod");
        System.out.println(configDir); // config/environments/prod on Unix, config\environments\prod on Windows

        // Safely join path segments
        var baseDir = Path.of("/var", "app");
        var logFile = baseDir.resolve("logs").resolve("app.log");
        System.out.println(logFile); // /var/app/logs/app.log

        // Handle absolute paths correctly
        var userPath = Path.of("/tmp/data");
        var result = baseDir.resolve(userPath); // Returns /tmp/data, not /var/app/tmp/data

        // Compute relative paths between locations
        var sourceDir = Path.of("/home", "user", "project", "src");
        var targetDir = Path.of("/home", "user", "project", "target", "classes");
        var relativePath = sourceDir.relativize(targetDir);
        System.out.println(relativePath); // ../target/classes

        // Clean up redundant path segments
        var messyPath = Path.of("data", "cache", "..", "logs", ".", "app.log");
        var cleanPath = messyPath.normalize();
        System.out.println(cleanPath); // data/logs/app.log
    }
}

